use rk3588_boot_support::{DelayUs,Mmio32,RetryAction};use crate::stage8::PcieBootConfig;use crate::stage11::{PhyInitOutcome,prepare_and_poll_phy};use crate::stage14::{HotResetWait,LinkWaitError,wait_hot_reset_or_l2,wait_link_up};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct EndpointBootReport{pub phy_status:u32,pub phy_aux:u32,pub link_status:u32,pub hot_reset:HotResetWait}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum EndpointBootError{PhyRetry(RetryAction),Link(LinkWaitError)}
pub fn run_endpoint_boot_flow<I:Mmio32+DelayUs>(io:&mut I,cfg:PcieBootConfig,cfg_base:u64,ctrl_base:u64,vendor:u16,device:u16,link_samples:u32)->Result<EndpointBootReport,EndpointBootError>{crate::stage12::apply_phy_mode_prelude(io,cfg.phy_mode);let(phy_status,phy_aux)=match prepare_and_poll_phy(io,cfg){PhyInitOutcome::Locked{status,aux}=>(status,aux),PhyInitOutcome::Retry(a)=>return Err(EndpointBootError::PhyRetry(a))};crate::stage13::program_endpoint_identity_and_width(io,cfg_base,vendor,device,cfg.generation,cfg.lanes);let link_status=wait_link_up(io,ctrl_base,link_samples).map_err(EndpointBootError::Link)?;let hot_reset=wait_hot_reset_or_l2(io,ctrl_base);Ok(EndpointBootReport{phy_status,phy_aux,link_status,hot_reset})}
#[cfg(test)]mod tests{use super::*;struct M{status:u32,link:u32,hot:u32,count:u32,magic:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{0xFD5B8904=>self.status,0xFD5B8A04=>0,0xFF010000=>self.magic,0xFF010004=>self.count,768=>self.link,16=>self.hot,_=>0}}fn write32(&mut self,a:u64,v:u32){if a==0xFF010000{self.magic=v}if a==0xFF010004{self.count=v}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn flow(){let mut m=M{status:0xF,link:0x30000,hot:4,count:0,magic:0};let cfg=PcieBootConfig{phy_mode:0,generation:3,lanes:1};let r=run_endpoint_boot_flow(&mut m,cfg,0,0,0x1d87,0x356a,5).unwrap();assert_eq!(r.phy_status,0xF);assert_eq!(r.link_status,0x30000);assert_eq!(r.hot_reset,HotResetWait::Observed);}}
